  "chain": "<span class=\"tok-dim\"># Three failed sign-ins are reported. The service writes each one down; every row carries a keyed hash of the row before it.</span>\n<span class=\"tok-k\">→ GET /v1/audit/verify</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;ok&quot;: true,\n  &quot;checked&quot;: 3\n}\n\n<span class=\"tok-dim\"># Someone with access to the database edits one address.</span>\nUPDATE audit_chain SET ip = '198.51.100.250' WHERE seq = 2;\n<span class=\"tok-k\">→ GET /v1/audit/verify</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;ok&quot;: false,\n  &quot;checked&quot;: 1,\n  &quot;problem&quot;: {\n    &quot;seq&quot;: 2,\n    &quot;reason&quot;: &quot;row_hash_mismatch&quot;\n  },\n  &quot;alarmed&quot;: true\n}\n\n<span class=\"tok-dim\"># Worse: they delete a row, or cut the end off. Each leaves a different mark.</span>\nDELETE FROM audit_chain WHERE seq = 2;\n<span class=\"tok-k\">→ GET /v1/audit/verify</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;ok&quot;: false,\n  &quot;problem&quot;: {\n    &quot;seq&quot;: 3,\n    &quot;reason&quot;: &quot;seq_gap&quot;,\n    &quot;expected&quot;: 2\n  }\n}\nDELETE FROM audit_chain WHERE seq = 3;   -- the last row\n<span class=\"tok-k\">→ GET /v1/audit/verify</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;ok&quot;: false,\n  &quot;problem&quot;: {\n    &quot;seq&quot;: 2,\n    &quot;reason&quot;: &quot;head_mismatch&quot;\n  }\n}\n\n<span class=\"tok-dim\"># The worst case: they also hold the signing key. They edit row 2 and recompute every hash after it. A receipt was taken earlier and kept elsewhere.</span>\n<span class=\"tok-k\">→ POST /v1/audit/anchor   (kept outside the database)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;seq&quot;: 3,\n  &quot;hash&quot;: &quot;&lt;hash&gt;&quot;\n}\n<span class=\"tok-k\">→ POST /v1/lab/tamper   {&quot;mode&quot;:&quot;rewrite&quot;,&quot;seq&quot;:2}</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;done&quot;: &quot;edited entry #2 and recomputed every hash after it, with the signing key&quot;,\n  &quot;seq&quot;: 2\n}\n\n<span class=\"tok-dim\"># On its own, the chain is consistent again: nothing inside the database can tell.</span>\n<span class=\"tok-k\">→ GET /v1/audit/verify</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;ok&quot;: true,\n  &quot;checked&quot;: 3\n}\n\n<span class=\"tok-dim\"># Against the receipt, it is not.</span>\n<span class=\"tok-k\">→ POST /v1/audit/verify   {&quot;anchor&quot;: &lt;the receipt&gt;}</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;ok&quot;: false,\n  &quot;problem&quot;: {\n    &quot;seq&quot;: 3,\n    &quot;reason&quot;: &quot;anchor_mismatch&quot;\n  },\n  &quot;alarmed&quot;: true\n}",
